pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    SigMaker maker;
    Dumb dumb;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new SigMaker();
        dumb = new Dumb();
    }

    function testFuzz_property(uint256 nonce, uint256 expiration, uint256 duration, bytes32 sigSeed) public {
        nonce = bound(nonce, 0, type(uint256).max);
        duration = bound(duration, 1, 10_000 days - 1);
        vm.warp(1000);
        vm.assume(expiration > block.timestamp);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        uint256[] memory noFloorIds = new uint256[](0);
        bytes[] memory sigs = new bytes[](1);
        sigs[0] = abi.encodePacked(sigSeed, sigSeed, uint8(27));

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(dumb),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // maker (ERC1271 signer contract) fills its own long call order; premium/strike are 0 so no token flows
        vm.prank(address(maker));
        c.fillOrder(order, sigs[0], noFloorIds);

        bytes32 orderHash = c.hashOrder(order);
        // pre-condition of the rule: maker owns the long position token
        require(c.ownerOf(uint256(orderHash)) == address(maker), "setup failed");

        // exercising burns the long position via transferFrom(msg.sender, 0xdead, id)
        vm.prank(address(maker));
        c.exercise(order, new uint256[](0));

        bool burned;
        try c.ownerOf(uint256(orderHash)) {
            burned = false;
        } catch {
            burned = true;
        }

        assertTrue(burned, "exercised long position must no longer be owned");
    }
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract Dumb {
    fallback() external payable {}
}

