pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    EIP1271Signer signer;
    MockToken token;

    function setUp() public {
        c = new C("", 0, address(this));
        signer = new EIP1271Signer();
        token = new MockToken();
        vm.warp(1000);
    }

    function testFuzz_property(address actor, address recipient, uint256 expiration) public {
        vm.assume(actor != address(0) && recipient != address(0) && actor != recipient);
        vm.assume(expiration > 2000 && expiration < 10_000);

        C.Order memory order;
        order.maker = address(signer);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(token);
        order.strike = 0;
        order.premium = 0;
        order.duration = 100;
        order.expiration = expiration;
        order.nonce = 0;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        vm.prank(actor);
        uint256 positionId = c.fillOrder(order, "", new uint256[](0));

        // The position NFT is now owned by the filler (actor).
        assertTrue(c.ownerOf(positionId) == actor, "minted to filler");

        // Authorized transfer must move ownership to the recipient.
        vm.prank(actor);
        c.transferFrom(actor, recipient, positionId);

        assertTrue(c.ownerOf(positionId) == recipient);
    }
}

