pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C("", 0, address(this));
    }

    function testFuzz_property(address recipient, address recipient2, uint256 duration) public {
        // keep params in the admissible domain
        recipient = address(uint160(bound(uint160(recipient), 1, type(uint160).max)));
        recipient2 = address(uint160(bound(uint160(recipient2), 1, type(uint160).max)));
        vm.assume(recipient != address(this));
        vm.assume(recipient2 != address(this));
        duration = bound(duration, 0, 9_000 days);

        vm.warp(0);

        // adversarial counterparties: a contract maker that validates any EIP-1271
        // signature, doubling as the silent baseAsset whose raw calls succeed
        ERC1271Maker maker = new ERC1271Maker();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(maker),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);

        // mint the maker's position NFT (id = orderHash) via the public entry
        c.fillOrder(order, bytes(""), floorAssetTokenIds);
        uint256 id = uint256(c.hashOrder(order));

        // maker (the token owner) approves an arbitrary fuzzer-supplied actor
        address actor = address(new ERC1271Maker());
        vm.prank(address(maker));
        c.approve(actor, id);

        // authorized transfer of the position NFT to the fuzzer's recipient
        vm.prank(actor);
        c.transferFrom(address(maker), recipient, id);

        // GENERAL RULE: the recorded recipient of a transferred token can always
        // transfer it onward. The mutant keeps the old owner in `_ownerOf`, so the
        // recipient is no longer authorized and this onward transfer reverts.
        vm.prank(recipient);
        bool ok;
        try c.transferFrom(recipient, recipient2, id) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract ERC1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    fallback() external {}
}

