pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address actor, address from, address to, uint256 id) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        // record the owner of id (if any) before the transfer
        address oldOwner = address(0);
        bool hadOwner = false;
        try c.ownerOf(id) returns (address o) {
            oldOwner = o;
            hadOwner = true;
        } catch {
            hadOwner = false;
        }

        vm.prank(actor);
        bool ok;
        try c.transferFrom(from, to, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful transferFrom implies `from` was the token's
        // true owner before the call (no transfer can originate from a non-owner,
        // and unminted tokens can never gain an owner via transferFrom).
        assertTrue(!ok || (hadOwner && oldOwner == from));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address from, address to, uint256 id) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        vm.assume(id != type(uint256).max);

        // id must be unminted before the call
        bool mintedBefore;
        try c.ownerOf(id) { mintedBefore = true; } catch { mintedBefore = false; }
        if (mintedBefore) return;

        // drive c through transferFrom; from is not the owner (id is unminted)
        vm.prank(from);
        try c.transferFrom(from, to, id) {} catch {}

        // rule: an unminted token id stays unminted after any transferFrom attempt
        bool unmintedAfter;
        try c.ownerOf(id) { unmintedAfter = false; } catch { unmintedAfter = true; }
        assertTrue(unmintedAfter);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce,
        uint256 expiration,
        address actor
    ) public {
        vm.assume(actor != address(0));
        duration = bound(duration, 0, 10_000 days - 1);
        vm.assume(expiration > block.timestamp);

        // Adversarial counterparties: a contract maker whose IERC1271 signature
        // always validates, and a fake ERC20 base asset that accepts transfers.
        Signer maker = new Signer();
        FakeERC20 base = new FakeERC20();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(base),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // Mint the long position to this test contract (signature validated via
        // the IERC1271 helper contract).
        bytes memory sig = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);
        uint256 positionId = c.fillOrder(order, sig, floorAssetTokenIds);

        // Rule: an NFT transfer whose recipient is the zero address must ALWAYS
        // revert (INVALID_RECIPIENT); no position can ever end up owned by 0.
        vm.prank(actor);
        bool ok;
        try c.transferFrom(actor, address(0), positionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "transfer to zero address must revert");
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e; // IERC1271.isValidSignature.selector
    }
}

contract FakeERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
